        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 403 not defined for path '/users/{username}/permission'.
        headers = {}
        headers["Authorization"] = auth_bob # bob
        headers["content-type"] = "application/json"
        body = {}
